"""Generate half-normal MGF fixtures."""

import os
import json
import numpy as np
from scipy.special import erf

# Get the file path:
FILE = os.path.realpath(__file__)

# Extract the directory in which this file resides:
DIR = os.path.dirname(FILE)


def halfnormal_mgf(t, sigma):
    """
    Moment generating function of HalfNormal(sigma).
    M(t) = exp((sigma^2 * t^2)/2) * (1 + erf(sigma * t / sqrt(2)))
    """
    return np.exp(0.5 * (sigma * t) ** 2) * (
        1.0 + erf(sigma * t / np.sqrt(2.0))
    )


def gen(t, sigma, name):
    """Generate fixture data and write to file.

    # Arguments
    * `t`: input values
    * `sigma`: scale parameters (σ > 0)
    * `name::str`: output filename

    # Examples
    ``` python
    python> t = np.random.rand(10) * 5.0
    python> sigma = np.random.rand(10) * 5.0 + 0.1
    python> gen(t, sigma, './data.json')
    ```
    """
    # Compute half-normal MGF values:
    y = halfnormal_mgf(t, sigma)

    # Store data to be written to file:
    data = {
        "t": t.tolist(),
        "sigma": sigma.tolist(),
        "expected": y.tolist()
    }

    # Based on the script directory, create an output filepath:
    filepath = os.path.join(DIR, name)

    # Write the data to the output filepath as JSON:
    with open(filepath, "w", encoding="utf-8") as outfile:
        json.dump(data, outfile)
        outfile.write("\n")


def main():
    """Generate fixture data."""
    # Generate random test values:
    n = 1000
    t = np.random.rand(n) * 5.0
    sigma = np.random.rand(n) * 5.0 + 0.1

    gen(t, sigma, "data.json")


if __name__ == "__main__":
    main()
